import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup preserving order
console.log(JSON.stringify(uniqueStrings(['a','b','a','c','b'])));

// Case-insensitive dedup, original spelling preserved
console.log(JSON.stringify(uniqueStrings(['Apple','apple','APPLE','Banana','banana'])));

// Whitespace not trimmed
console.log(JSON.stringify(uniqueStrings([' a ','a',' a '])));

// Input not mutated
const input = ['x','X','y','x'];
const out = uniqueStrings(input);
console.log(JSON.stringify(input), JSON.stringify(out));

// Empty array
console.log(JSON.stringify(uniqueStrings([])));

// Mixed case with distinct keys
console.log(JSON.stringify(uniqueStrings(['Hello','hello','HELLO','World','world'])));
